@import "~bootstrap/dist/css/bootstrap.css";

body {
  background: #edf2f9;
  color: #1f2a44;
}

.container {
  max-width: 1180px;
}

ul.techList {
    list-style-type: none;
    padding: 0;
    margin: 0;
}

ul.techList li {
    background: #f8f8f8;
    border: 1px solid #ddd;
    border-radius: 5px;
    padding: 8px 13px;
    margin-bottom: 10px;
}

ul.techList.error li {
    color: red;
    background: rgba(255,0,0,0.08);
    border-color: red;
}

ul.techList.completed li {
    color: #3dd843;
    background: rgba(61,216,67,0.08);
    border-color: #3dd843;
}
